/** 
 * {@inheritDoc}<p>The default  {@link AbstractFuture} implementation throws {@code InterruptedException} if thecurrent thread is interrupted during the call, even if the value is already available.
 * @throws CancellationException {@inheritDoc}
 */
@CanIgnoreReturnValue @Override public V get() throws InterruptedException, ExecutionException {
  try {
    if (Thread.interrupted()) {
      throw new InterruptedException();
    }
    Object localValue=value;
    if (localValue != null & !(localValue instanceof SetFuture)) {
      return getDoneValue(localValue);
    }
    Waiter oldHead=waiters;
    if (oldHead != Waiter.TOMBSTONE) {
      Waiter node=new Waiter();
      do {
        node.setNext(oldHead);
        if (ATOMIC_HELPER.casWaiters(this,oldHead,node)) {
          while (true) {
            LockSupport.park(this);
            if (Thread.interrupted()) {
              removeWaiter(node);
              throw new InterruptedException();
            }
            localValue=value;
            if (localValue != null & !(localValue instanceof SetFuture)) {
              return getDoneValue(localValue);
            }
          }
        }
        oldHead=waiters;
      }
   while (oldHead != Waiter.TOMBSTONE);
    }
    return getDoneValue(value);
  } catch (IllegalArgumentException e) {
    throw new ExecutionException(e);
  }
}
